import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"地水师","description":"周易折中 - 地水师","frontmatter":{"title":"地水师","description":"周易折中 - 地水师"},"headers":[],"relativePath":"zh/classics/zhezhong/013.md","filePath":"zh/classics/zhezhong/013.md"}'),h={name:"zh/classics/zhezhong/013.md"};function n(p,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="地水师" tabindex="-1">地水师 <a class="header-anchor" href="#地水师" aria-label="Permalink to “地水师”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>序卦曰：讼必有众起，故受之以师。师之兴，由有争也，所以次讼也。为卦坤上坎下，以二体言之，地中有水，为众聚之象；以二卦之义言之，内险外顺，险道而以顺行，师之义也。以爻言之，一阳而为众阴之主，统众之象也。比以一阳为众阴之主而在上，君之象也；师以一阳为众阴之主而在下，将帅之象也。</p><p>师：贞，丈人吉，无咎。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>师，兵众也。下坎上坤，坎险坤顺，坎水坤地。古者寓兵于农，伏至险于大顺，藏不测于至静之中。又卦惟九二一阳居下卦之中，为将之象；上下五阴顺而从之，为众之象。九二以刚居下而用事，六五以柔居上而任之，为人君命将出师之象。故其卦之名曰师。丈人，长老之称。用师之道，利于得正而任老成之人，乃得吉而无咎。戒占者亦必如是也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>师之道以正为本，兴师动众以毒天下，而不以正，民弗从也，强驱之耳。故师以贞为主，其动虽正也，帅之者必丈人，则吉而无咎也。盖有吉而有咎者，有无咎而不吉者，吉且无咎，乃尽善也。文人者，尊严之称。帅师总众，非众所尊信畏服，则安能得人心之从？故司马穣苴擢自微贱，授之以众，乃以众心未服，请庄贾为将也。所谓丈人不必素居崇贵，但其才谋徳业，众所畏服，则是也。如穣苴既诛庄贾，则众心畏服，乃丈人矣。又如淮阴侯起于微贱，遂为大将，盖其谋为有以使人尊畏也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：兴役动众无功罪也，故吉乃无吉。</p></li><li><p>朱子语类云：吉无咎，谓如一件事，自家作出来好，方得无罪咎。若作得不好，虽是好事也，则有咎。</p></li></ul><p>象曰：地中有水，师。君子以容民畜众</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>水不外于地，兵不外于民，故能养民则可以得众矣。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>地中有水，水聚于地中为众聚之象，故为师也。君子观地中有水之象，以容保其民，畜聚其众也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li>陈氏琛曰：地中有水，犹民中有兵，非师之象乎？君子观师之象，必容保其民，必畜其兵众焉。盖田以民分，兵以赋出，故当无事之时，必制田里，教树畜，使比闾族党州乡之民无不各得其养。民既有养，则所谓伍两卒旅军师之众，以为他日折冲御侮之用者，皆畜于此矣。苟平时诲之无其方，则缓急谁复为之用哉？</li></ul><p>彖曰：师，众也，贞，正也。能以众正，可以王矣。</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>此以卦体释师贞之义，以谓能左右之也。一阳在下之中，而五阴皆为所以也。能以众正则王者之师矣。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>能使众人皆正，可以王天下矣。得众心服从而归正，王道止于是也。</p><p>刚中而应，行险而顺，以此毒天下而民从之，吉，又何咎矣。</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>又以卦体卦徳释丈人吉无咎之义。刚中谓九二，应谓六五。应之行险谓行危道，顺谓顺人心。此非有老成之徳者不能也。毒害也，师旅之兴不无害于天下，然以其有是才徳，是以民悦而从之也。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>言二也以刚处中，刚而得中道也。六五之君为正应，信任之专也。虽行险道而以顺动，所谓义兵，王者之师也。上顺下险，行险而顺也。师旅之兴，不无伤财害人，毒害天下。然而民心从之者，以其义动也。古者东征西怨，民心从也如是，故吉而无咎。吉谓必克，无咎谓合义，又何咎矣。其义故无咎也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>游氏酢曰：用师之道，将以正天下之不正也。故师谓之征，己则不正，其能正人乎？刚中而应，任将之道也；行险而顺，兴师之义也。仰顺乎天，无违天以干时；俯顺乎人，无咈人以从欲。兴师之顺如此，故能以众正。以众正之，则人皆知其欲正己而已，天下孰不趋于正哉？</p></li><li><p>胡氏炳文曰：“毒”之一字，见得王者之师不得已而用之，如毒药之攻病，非有沈痾坚症不轻用也。其指深矣。</p></li></ul><p>初六：师出以律，否臧凶。</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>律，法也。否臧，谓不善也。晁氏曰：否字先儒多作不是也。在卦之初，为师之始。出师之道当谨其始，以律则吉，不臧则凶。戒占者当谨始而守法也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>初，师之始也，故言出师之义及行师之道。在邦国兴师而言，合义理则是以律法也，谓以禁乱诛暴而动。苟动不以义，则虽善亦凶道也。善谓克胜，凶谓殃民害义也。在行师而言，律谓号令节制。行师之道以号令节制为本，所以统制于众。不以律，则虽善亦凶，虽使胜捷犹凶道也。制师无法，幸而不败且胜者，时有之矣，圣人之所戒也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：为师之始，齐师者也。齐众以律，失律则散。</p></li><li><p>程子曰：律有二义，有出师不以义者，有行师而无号令节制者，皆失律也。</p></li><li><p>胡氏炳文曰：初六才柔，故有否臧之戒。然以律不言吉，否臧则言凶者，律令谨严，出师之常，其胜负犹未可知也，故不言吉。出而失律，凶立见矣。</p></li></ul><p>象曰：师出以律，失律凶也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>师出当以律，失律则凶矣。虽幸而胜，亦凶道也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>蔡氏清曰：不曰“否臧凶”，而曰“失律凶”者，明否臧之为失律也。</li></ul><p>九二：在师中，吉，无咎，王三锡命。</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>九二在下，为众阴所归，而有刚中之徳，上应于五，而为所宠任，故其象占如此。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>师卦惟九二一阳为众阴所归，五居君位，是其正应。二乃师之主，专制其事者也。居下而专制其事，惟在师则可。自古命将，阃外之事得专制之。在师专制而得中道，故吉而无咎。盖恃专则失为下之道，不专则无成功之理，故得中为吉。凡师之道，威和并至则吉也。既处之尽其善，则能成功而安天下，故王锡宠命至于三也。凡事至于三者极也。六五在上，既专倚任，复厚其宠数。盖礼不称则威不重，而下不信也。它卦九二为六五所任者有矣，惟师专主其事，而为众阴所归，故其义最大。人臣之道，于事无所敌专，惟阃外之事则专制之。虽制之在已然，因师之力而能致者，皆君所与而职当为也。世儒有论鲁祀周公以天子礼乐，以为周公能为人臣不能为之功，则可用人臣不得用之礼乐。是不知人臣之道也。夫居周公之位，则为周公之事。由其位而能为者，皆所当为也。周公乃尽其职耳。子道亦然。惟孟子为知此义，故曰：事亲若曽子者可也。未尝以曽子之孝为有馀也。盖子之身所能为者，皆所当为也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰：承上之宠，为师之主任。大役重，无功则凶，故吉乃无咎。王三锡命者，以其有功，故王三加锡命。</p></li><li><p>朱子语类云：在师中，吉言以刚中之徳在师中，所以为吉。</p></li><li><p>胡氏炳文曰：卦辞师贞丈人吉无咎，爻在师中吉无咎，即卦辞意也。中则无过不及，所以为贞；在师而中，所以为丈人。故师六爻，惟九二吉无咎。</p></li></ul><p>象曰：在师中吉，承天宠也。王三锡命，怀万邦也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>在师中吉者，以其承天之宠任也。天谓王也，人臣非君宠任之，则安得专征之权而有成功之吉象？以二专主其事，故𤼵此义与前所云世儒之见异矣。王三锡以恩命褒其成功，所以懐万邦也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>干氏宝曰：锡命非私也，安万邦而已。</p></li><li><p>丘氏富国曰：王者用兵，非得已嗜杀，岂其本心？故三锡之命，惟在于懐绥万邦而已。</p></li><li><p>谷氏家杰曰：不曰“威”而曰“懐”，见王者用师之本心。</p></li></ul><p>六三：师或舆尸，凶。</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>舆尸，谓师徒挠败，舆尸而归也。以阴居阳，才弱志刚，不中不正而犯非其分，故其象占如此。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>三居下卦之上，居位当任者也。不唯其才阴柔不中正，师旅之事任当专一。二既以刚中之才为上信倚，必专其事乃有成功。若或更使众人主之，凶之道也。舆尸，众主也。盖指三而言。以三居下之上，故发此义。军旅之事，任不专一，覆败必矣。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏申子曰：三不中不正，以柔居刚，是小人之才弱志刚者，而居二之上，是二为主将，三躐而尸之也。凡任将不专，偏禆擅命，权不出一者，皆舆尸也。军旅何所聴命乎？其取败必矣。</li></ul><p>象曰：师或舆尸，大无功也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>倚付二三，安能成功？岂唯无功，所以致凶也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏简曰：行师之法，权归一将。使众主之，凶之道也。众所不一，必无成功。九二既作帅，六三居二之上，有权不归一之象。</li></ul><p>六四：师左次，无咎。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>左次，谓退舍也。阴柔不中，而居阴得正，故其象如此。全师以退，贤于六三逺矣，故其占如此。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>师之进以强勇也。四以柔居阴，非能进而克捷者也。知不能进而退，故左次。左次，退舍也。量宜进退，乃所当也，故无咎。见可而进，知难而退，师之常也。惟取其退之得宜，不论其才之能否也。度不能胜而完师以退，愈于覆败逺矣。可进而退，乃为咎也。易之发此义，以示后世，其仁深矣。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>吴氏澄曰：按兵家尚右，右为前，左为后。故八阵图，天前冲、地前冲在右，天后冲、地后冲在左。</li></ul><p>象曰：左次无咎，未失常也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>知难而退，师之常也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>行师之道，因时施宜，乃其常也。故左次未为失也。如四退次，乃得其宜，是以无咎。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏时曰：师以右为主常也，左次则失常矣。然四以柔顺之资，量敌而后进，虑胜而后㑹退，而左次未为失常也。</li></ul><p>六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>六五用师之主，柔顺而中，不为兵端者也。敌加于已，不得已而应之，故为田有禽之象，而其占利以搏执而无咎也。言语辞也。长子九二也，弟子三四也。又戒占者专于委任，若使君子任事而又使小人参之，则是使之舆尸而归，故虽贞而亦不免于凶也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>五君位，兴师之主也，故言兴师任将之道。师之兴，必以蛮夷猾夏，寇贼奸宄为生民之害，不可懐来，然后奉辞以诛之。若禽兽入于田中，侵害稼穑，于义宜猎取，则猎取之。如此而动，乃得无咎。若轻动以毒天下，其咎大矣。执言，奉辞也，明其罪而讨之也。若秦皇、汉武，皆穷山林以索禽兽者也，非田有禽也。任将授师之道，当以长子帅师。二在下而为师之主，长子也。若以弟子众主之，则所为虽正亦凶也。弟子，凡非长者也。自古任将不专而致覆败者，如晋荀林父邲之战，唐郭子仪相州之败是也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰：阴不先唱，柔不犯物，犯而后应，故往即有功。犹如田中有禽而来犯苖，若往猎之则无咎过。</p></li><li><p>朱子语类云：问易爻取义，如师之五“长子帅师”，乃是本爻有此象，又却说“弟子舆尸”，何也？曰此假设之辞也。言若弟子舆尸，则凶矣。问此例恐与家人“嗃嗃而继以妇子嘻嘻”同。曰然。</p></li><li><p>胡氏炳文曰：长子即彖所谓丈人也。自众尊之，则曰丈人；自君称之，则曰长子，皆长老之称。</p></li><li><p>蒋氏悌生曰：舆尸，程传训众主，朱义训挠败。但训作众主，则与长子帅师为反对其义尤切。禽在山林固无事于猎取，今入于田，则害我禾稼，畋而执之宜也。长子帅师可也，又使弟子众主之，是自取凶咎也。</p></li><li><p>蔡氏清曰：田有禽利执言，是师贞意；长子帅师，是丈人意。</p></li></ul><p>象曰：长子帅师，以中行也。弟子舆尸，使不当也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>长子谓二，以中正之德合于上而受任以行。若复使其馀者众尸其事，是任使之不当也，其凶宜矣。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖达曰：“以中行”是九二居中也；“使不当”谓六三失位也。</li></ul><p>上六：大君有命，开国承家，小人勿用。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>师之终，顺之极，论功行赏之时也。坤为土，故有开国承家之象。然小人则虽有功，亦不可使之得有爵土，但优以金帛可也。戒行赏之人于小人则不可用，此占而小人遇之，亦不得用此爻也。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>上师之终也，功之成也。大君以爵命赏有功也。开国，封之为诸侯也。承家，以为卿大夫也。承受也。小人者，虽有功不可用也，故戒使勿用。师旅之兴，成功非一道，不必皆君子也，故戒以小人有功不可用也。赏之以金帛禄位可也，不可使有国家而为政也。小人平时易致骄盈，况挟其功乎？汉之英、彭所以亡也，圣人之深虑远戒也。此专言师终之义，不取爻义。盖以其大者，若以爻言，则六以柔居顺之极，师既终而在无位之地，善处而无咎者也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云：开国承家，小人勿用。旧时说只作论功行赏之时，不可及小人。今思他既一例有功，如何不及他得？看来开国承家一句是公共得底，未分别君子小人；在小人勿用，则是勿更用他与之谋议经画耳。汉光武能用此义，自定天下之后，一例论功行封，其所以用之在左右者，则邓禹、耿弇、贾复数人，他不与焉。此义方思量得如此，未曽改入本义，且记取。</p></li><li><p>赵氏汝梅曰：大君，六五也。周官军将皆命卿，开国者出封为诸侯，师帅皆中大夫，旅帅皆下大夫，承家者大夫之采邑。 又曰：知勇之人不能皆全材，用于戎行有将帅节制于上，未见其害；今为国为家，有民人有社稷，则不可属之小人。</p></li><li><p>又曰：知勇之人不能皆全材，用于戎行有将帅节制于上，未见其害；今为国为家，有民人有社稷，则不可属之小人。</p></li><li><p>胡氏炳文曰：初师之始，故纪其出师而有律；上师之终，故纪其还师而赏功。六爻中，将兵、将将、伐罪、赏功，靡所不载，不曰小人勿用，则又戒辞也。虽然，亦在于谨其始焉耳。曰丈人，曰长子，用以行师者得其人，及其开国承家，自不至于用小人矣。</p></li><li><p>林氏希元曰：小人立功，不得不一例赏以爵邑。若一例赏以爵邑，又恐播恶于众，不若于行师之初不用之为愈也。故象传谓其必乱邦，彖辞于师贞之下即言宜用丈人，五爻之辞又戒用弟子，即此意也。师之始既言之，师之终而复言，正戒人当谨于其始也。案小人勿用，非既用而不封，亦非既封而不用，乃是从初不用。所谓丈人吉，弟子凶者，自其出师之始而已然也。胡氏林氏之说皆合卦意。但此处小人勿用，小人二字又似所包者广，盖非专论在师立功之人，乃是谓乱定之后建官惟贤，不可复用小人，恐为他日之乱本尔。如解卦难既平矣，必曰小人退；既济卦三年克之矣，又必曰小人勿用，皆此意也。</p></li></ul><p>象曰：大君有命，以正功也。小人勿用，必乱邦也</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>圣人之戒深矣。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>大君持恩赏之柄，以正军旅之功，师之终也。虽赏其功，小人则不可以有功而任用之，用之必乱邦。小人恃功而乱邦者，古有之矣。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏简曰：师之终，功成。大君有命，所以赏功也。“正功”言赏必当，功不可差失也。开国承家之始，其初不可用小人也。于此始言“勿用”者，困此赏功原其始也。用小人为将帅，幸而成功，则难于不赏；使之开国承家，则害及民，必乱邦也。去一害民者，又用一害民者，以乱易乱，必不可。</p></li><li><p>胡氏炳文曰：王三锡命，命于行师之始；大君有命，命于行师之终。懐邦乱邦，丈人小人之所以分，此固圣人之所深虑远戒也。</p></li><li><p>邵氏宝曰：“弟子舆尸”戒于师始，“小人勿用”戒于师终。始无弟子，则终无小人；即使有之，或赏而不封，或封而不任，不任亦不用也。</p></li></ul>',105)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
